_Static_assert(_Alignof(SW_UdpFrame_Impl) == 1, "SW_UdpFrame_Impl: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_UdpFrame_Impl, headers) == 0, "SW_UdpFrame_Impl: memory layout differs from HAMR's");
